import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('napkin-dermatitis',
  kf=["Inflammation of the skin under a nappy, most often **irritant** contact dermatitis from urine, faeces and occlusion.",
      "Peaks at **9–12 months** (range 3–15 months); much less common with modern breathable disposables.",
      "Irritant: convex surfaces affected, **skin creases spared**; *Candida*: creases involved with **satellite** papules.",
      "Frequent changes, nappy-free time, gentle cleansing and a **barrier preparation**; topical imidazole if candidal; hydrocortisone 1% short term if inflamed.",
      "Refer if atypical, nodular, ulcerated or not responding (e.g. psoriasis, Langerhans cell histiocytosis, zinc deficiency)."],
  epi=[{"t": "**Who**", "sub": ["Up to a third of babies in nappies at any time; peak 9–12 months.", "Also affects incontinent older children and adults (incontinence-associated dermatitis)."]}],
  aet=["Prolonged contact with urine and faeces; **diarrhoea** (faecal enzymes) and antibiotics (Candida) are common triggers.", "Infrequent changes, tight nappies, harsh wipes and soaps."],
  myths=["**\"Leave the cream thick and never wipe it off\"**: a barrier layer is fine, but clean skin gently at each change."],
  patho_lead="Wet, occluded skin with a **high pH** lets faecal enzymes break down the barrier.",
  mech=[("Overhydration", "Occlusion keeps the stratum corneum wet, making it fragile and more permeable."),
        ("Alkaline pH and enzymes", "Bacteria convert urine urea to **ammonia**, raising pH, which activates faecal **proteases and lipases** that digest the skin barrier."),
        ("Irritant dermatitis", "Friction and enzymes inflame the convex skin in contact with the nappy; creases are protected.", "v3-napkin-irritant-vs-candida.jpg", "Irritant napkin dermatitis (convex surfaces, creases spared) vs candidal (creases involved, satellite spots)."),
        ("Secondary Candida", "After about 3 days, *Candida* from the gut often colonises damaged skin, spreading into the folds.")],
  histo=["Not needed; diagnosis is clinical. Swab satellite pustules if unsure or recurrent."],
  special=[{"t": "**Skin of colour**", "sub": ["Redness is less obvious; look for scaling, erosion and post-inflammatory pigmentation."]}],
  comp=["Secondary *Candida* or bacterial (impetigo) infection.", "Erosive **Jacquet** dermatitis and granuloma gluteale infantum (steroid misuse).", "Distress and sleep disturbance."],
  prog=["Usually settles within days with good nappy care; recurs with diarrhoea or infrequent changes."],
  see_also=["candida-intertrigo", "seborrhoeic-keratosis" if False else "eczema-dermatitis", "psoriasis", "neonatal-rashes"])

E('actinic-keratoses',
  kf=["**Actinic (solar) keratoses** are UV-induced patches of dysplastic keratinocytes on chronically sun-exposed skin.",
      "Very common: up to **25% of people over 60** in northern England and Ireland; more in fair skin, outdoor workers and the immunosuppressed.",
      "Rough, **gritty** scale on a pink base, often easier to feel than see; face, bald scalp, ears, forearms and backs of hands.",
      "A single AK rarely becomes SCC, but people with **many AKs** have a 10–15% lifetime SCC risk (field cancerisation).",
      "Sun protection for all; cryotherapy for few lesions; **field treatment** (5-FU, imiquimod, diclofenac 3%, PDT). Tender, thick or growing → exclude SCC."],
  epi=[{"t": "**Who**", "sub": ["Older adults with fair skin (Fitzpatrick I–II), chronic sun exposure and photoageing.", "Organ transplant recipients and other immunosuppressed people have many more, and more aggressive, lesions."]},
       {"t": "**Natural history**", "sub": ["Individual AKs can regress (up to a quarter a year), persist or, rarely, progress to SCC."]}],
  aet=["Cumulative **UVB** (and UVA) exposure: outdoor work, sunbeds, living in sunny climates.", "Immunosuppression (transplant drugs), older age, previous skin cancer; HPV types may contribute."],
  myths=["**\"It's just dry skin\"**: a persistent gritty patch on sun-damaged skin is an AK until shown otherwise.", "**\"Treat each spot\"**: once cancer is excluded, treating the whole field matters more."],
  patho_lead="UV damage to keratinocyte DNA creates a **field** of genetically abnormal cells; the AK is the visible tip.",
  mech=[("UV DNA damage", "UVB forms pyrimidine dimers; mutations in **TP53** let damaged keratinocytes survive and divide."),
        ("Clonal expansion", "Mutated clones spread along the basal layer, producing **dysplasia** of the lower epidermis.", "v3-ak-vs-sk-section.jpg", "Actinic keratosis (left: rough scale over dysplastic epidermis) compared with a benign seborrhoeic keratosis (right)."),
        ("Abnormal keratinisation", "Dysplastic cells make abnormal keratin, giving adherent, rough **parakeratotic** scale."),
        ("Field cancerisation", "Surrounding sun-damaged skin carries similar mutations, so new AKs and SCCs arise across the field.", "v3-ak-scalp-field.jpg", "Multiple AKs across a sun-damaged bald scalp."),
        ("Progression", "If dysplasia becomes full-thickness (Bowen's disease) or invades the dermis, it has become SCC.")],
  histo=["Atypical keratinocytes in the **basal layer** (partial-thickness dysplasia), with parakeratosis that spares the follicular openings (alternating pink and blue).",
         "Solar elastosis in the dermis.", "Biopsy if thick, tender, ulcerated or not responding (to exclude SCC)."],
  special=[{"t": "**Immunosuppressed (transplant)**", "sub": ["Many AKs and high SCC risk: lower threshold for specialist referral and regular skin checks."]},
           {"t": "**Lips (actinic cheilitis)**", "sub": ["Blurred, scaly vermilion border of the lower lip; higher risk of SCC: lower threshold for specialist review."]}],
  comp=["Progression to **cutaneous SCC**.", "Cutaneous horn (may hide SCC).", "Inflammatory reactions to field treatments; cosmetic concern."],
  prog=["Chronic: new lesions keep appearing in sun-damaged skin.", "Treatment clears most lesions; ongoing sun protection and surveillance are needed."],
  quiz=[("Why treat a field of AKs rather than single spots?", "The whole sun-damaged area carries mutated cells (field cancerisation); treating it reduces new AKs and SCCs."),
        ("Which AK features suggest SCC?", "Tenderness, thickening, induration, rapid growth, ulceration or bleeding."),
        ("Name three field treatments.", "Topical 5-fluorouracil, imiquimod and diclofenac 3% gel; photodynamic therapy via dermatology."),
        ("What should patients expect from 5-FU or imiquimod?", "An inflammatory phase: redness, crusting and soreness before healing."),
        ("What is actinic cheilitis?", "Actinic keratosis of the lip vermilion; higher risk of SCC.")],
  see_also=["squamous-cell-carcinoma", "seborrhoeic-keratosis", "photoageing", "solar-lentigines"])

E('seborrhoeic-keratosis',
  kf=["Very common **benign** epidermal tumour: waxy, warty, **'stuck-on'** papules and plaques, tan to black.",
      "Over **90% of adults over 60** have at least one; usually start in the 30s–40s.",
      "Not premalignant; caused by clonal mutations (e.g. **FGFR3, PIK3CA**) in keratinocytes, not sebum or viruses.",
      "Dermoscopy: **milia-like cysts**, comedo-like openings, 'brain-like' ridges and sharp edges.",
      "Reassure if typical; refer anything atypical (melanoma mimic). Sudden eruption of many SKs (**Leser–Trélat**) may signal internal malignancy."],
  epi=[{"t": "**Who**", "sub": ["Extremely common in older adults of all ethnic groups; uncommon under 20.", "Numbers increase with age; a strong family tendency in some people."]},
       {"t": "**Variant in skin of colour**", "sub": ["**Dermatosis papulosa nigra**: many small dark papules on the face and neck, especially in people of African or Asian descent."]}],
  aet=["Clonal somatic mutations in **FGFR3, PIK3CA, RAS, AKT1, EGFR**.", "Sun exposure may contribute (more on exposed sites); friction in body folds.",
       "Eruptive SKs may follow inflammatory dermatoses or sunburn; **Leser–Trélat sign** with internal cancer is rare."],
  myths=["**\"It's from greasy skin\"**: the name is misleading; SKs are not related to sebum or sebaceous glands.", "**\"They are warts and spread\"**: they are not viral or contagious."],
  patho_lead="An SK is a **benign clonal overgrowth** of epidermal keratinocytes that sits on top of the skin.",
  mech=[("Clonal mutation", "Keratinocytes acquire activating mutations (often FGFR3 or PIK3CA) that drive orderly but excessive growth."),
        ("Upward growth", "The thickened epidermis grows **outwards above the skin surface**, so the lesion looks stuck on and can almost be lifted off.", "v3-sk-stuck-on.jpg", "A seborrhoeic keratosis sitting on the skin surface, with horn cysts within it."),
        ("Horn cysts and pigment", "Keratin collects in small cysts (milia-like cysts on dermoscopy); melanin transferred from melanocytes darkens many lesions."),
        ("Irritation", "Friction or trauma can inflame an SK, making it red, crusted or bleeding, which can mimic cancer.")],
  histo=["Acanthosis of basaloid keratinocytes with **horn pseudocysts**, hyperkeratosis and papillomatosis; the base is flat (the 'string sign').",
         "Variants: acanthotic, hyperkeratotic, reticulated, clonal, irritated. Biopsy if any doubt."],
  special=[{"t": "**Skin of colour**", "sub": ["Dermatosis papulosa nigra is common and benign; treat only for cosmetic reasons, with care to avoid pigment change."]}],
  comp=["Irritation, itch, catching on clothing and bleeding.", "**Misdiagnosis**: melanoma, pigmented BCC or SCC can look like an SK.", "Collision tumours (a cancer arising next to an SK) are rare."],
  prog=["Benign and permanent; new lesions keep appearing with age.", "Removal (cryotherapy, curettage, shave) is usually cosmetic and not funded on the NHS unless symptomatic."],
  see_also=["actinic-keratoses", "melanoma", "solar-lentigines", "melanocytic-naevi"])

E('basal-cell-carcinoma',
  kf=["The **commonest cancer in the UK**: a slow-growing, locally invasive tumour of basal keratinocytes that almost never metastasises.",
      "Mostly older, fair-skinned adults with sun damage; **80%** on the head and neck.",
      "Classic nodular BCC: **pearly** papule with rolled edge and **arborising telangiectasia**, often with central ulceration (rodent ulcer).",
      "Caused by **hedgehog pathway** mutations (PTCH1, SMO), usually from UV exposure.",
      "UK (NICE NG12): routine (not 2WW) referral for most suspected BCC; urgent if site or size threatens function. Surgery is the mainstay."],
  epi=[{"t": "**Incidence**", "sub": ["The commonest cancer in white populations; well over 100,000 new cases a year in the UK and rising.", "Lifetime risk about 1 in 5 in some fair-skinned populations."]},
       {"t": "**Who**", "sub": ["Usually over 60, more men; rare in people with dark skin but does occur (more often pigmented)."]}],
  aet=["**Intermittent intense UV** and childhood sunburn; fair skin, red or blond hair, freckling.", "Previous BCC (about 40% get another within 3 years), sunbeds, radiotherapy, arsenic.",
       "Immunosuppression, hydrochlorothiazide (possible), syndromes: **Gorlin (basal cell naevus) syndrome**, xeroderma pigmentosum."],
  myths=["**\"Skin cancer always spreads\"**: BCC rarely metastasises but can destroy local tissue if neglected.", "**\"It's a spot that keeps bleeding and healing\"**: a non-healing or recurrently bleeding spot needs review."],
  patho_lead="BCC grows from basal-layer cells when the **hedgehog signalling pathway** is switched on permanently.",
  mech=[("UV mutation", "UV damages **PTCH1** (a hedgehog-pathway brake) or activates **SMO**; TP53 mutations often coexist."),
        ("Uncontrolled hedgehog signalling", "GLI transcription factors stay on, so basaloid cells keep proliferating.", "v3-bcc-skin-section.jpg", "BCC in section: nests of basaloid cells growing from the basal layer into the dermis, with dilated vessels on the surface."),
        ("Local invasion", "Tumour nests depend on surrounding stroma, which is why BCC invades locally but rarely spreads by blood or lymph."),
        ("Growth patterns", "Nodular, superficial, infiltrative and **morphoeic** patterns differ in how far they extend beyond what is visible.", "v3-bcc-face-h-zone.jpg", "High-risk 'H-zone' of the face (eyes, nose, lips, ears), where BCCs are harder to treat."),
        ("Ulceration", "Central necrosis gives the classic **rodent ulcer**, with a rolled pearly edge.")],
  histo=["Nests of **basaloid cells** with peripheral **palisading**, retraction artefact and mucinous stroma.", "Subtype (nodular, superficial, infiltrative, morphoeic, micronodular) guides treatment and recurrence risk."],
  special=[{"t": "**Skin of colour**", "sub": ["Less common; often **pigmented** and mistaken for a naevus or melanoma."]},
           {"t": "**Young patients or many BCCs**", "sub": ["Consider Gorlin syndrome (jaw cysts, palmar pits) and refer."]}],
  comp=["Local tissue destruction (eye, nose, ear) if neglected.", "Recurrence, especially infiltrative/morphoeic BCC and H-zone sites.", "Further BCCs and other skin cancers.", "Metastasis is very rare (under 0.1%)."],
  prog=["Excellent: over 95% cure with standard excision.", "Annual skin self-checks and sun protection are needed because new BCCs are common."],
  see_also=["squamous-cell-carcinoma", "melanoma", "actinic-keratoses", "skin-surgery-procedures"])

E('squamous-cell-carcinoma',
  kf=["Malignant tumour of **epidermal keratinocytes**; the second commonest skin cancer.",
      "Risk factors: cumulative **UV**, older age, fair skin, **AKs**, organ-transplant immunosuppression (65–250× risk), smoking, chronic wounds and scars.",
      "Tender, **keratotic, crusted or ulcerated** nodule on sun-exposed skin that grows over weeks to months.",
      "Can metastasise (about 2–5%): **lip, ear**, large, deep, perineural and immunosuppressed are high risk.",
      "UK (NICE NG12): **suspected cancer (2WW) referral**; surgery is the mainstay."],
  epi=[{"t": "**Incidence**", "sub": ["Rising; about 1 in 4 non-melanoma skin cancers in the UK.", "Mostly over 60, more men; outdoor workers."]},
       {"t": "**High-risk groups**", "sub": ["Organ transplant recipients develop SCCs far more often and more aggressively.", "People with chronic lymphocytic leukaemia or HIV."]}],
  aet=["**Cumulative UVB**, sunbeds and PUVA; photosensitising drugs (voriconazole, hydrochlorothiazide).", "Precursors: AKs, Bowen's disease (SCC in situ), actinic cheilitis.",
       "**Chronic inflammation and scars**: burns, leg ulcers (Marjolin ulcer), lichen sclerosus, discoid lupus, epidermolysis bullosa.", "HPV (especially in immunosuppression and genital/periungual SCC), arsenic, ionising radiation, smoking."],
  myths=["**\"It's a wart that won't go\"**: a fast-growing, tender keratotic lump on sun-damaged skin needs urgent assessment."],
  patho_lead="SCC develops step by step from **UV-damaged keratinocytes** that eventually breach the basement membrane.",
  mech=[("UV DNA damage", "UVB causes **TP53** mutations (UV signature) and then NOTCH and CDKN2A changes."),
        ("Dysplasia", "Abnormal cells spread in the epidermis: partial thickness (AK) then full thickness (Bowen's disease, SCC in situ)."),
        ("Invasion", "Cells break through the basement membrane into the dermis as nests and strands of keratinising cells.", "v3-scc-invasion-section.jpg", "SCC invading through the basement membrane into the dermis, with keratin pearls."),
        ("Immune escape", "Immunosuppression lets mutated clones grow unchecked: why transplant recipients get many aggressive SCCs."),
        ("Spread", "Some tumours invade nerves or spread to regional lymph nodes, especially on high-risk sites.", "v3-scc-high-risk-sites.jpg", "High-risk sites: lip, ear, temple, scalp and the backs of the hands.")],
  histo=["Atypical keratinocytes invading the dermis with **keratin pearls** and intercellular bridges.", "Grade (well to poorly differentiated), depth, perineural invasion and margins determine risk and follow-up."],
  special=[{"t": "**Transplant recipients**", "sub": ["Annual or more frequent skin surveillance; rapid referral of any new or growing lesion."]},
           {"t": "**Skin of colour**", "sub": ["SCC is the commonest skin cancer in people with dark skin, often arising in **scars, chronic ulcers or sun-protected sites** and presenting late."]}],
  comp=["Local recurrence and tissue destruction.", "**Metastasis** to lymph nodes (about 2–5%), higher with high-risk features.", "Perineural spread (pain, numbness, cranial nerve palsies)."],
  prog=["Most low-risk SCCs are cured by excision.", "Five-year survival falls markedly once nodes are involved; high-risk patients need specialist follow-up."],
  see_also=["actinic-keratoses", "basal-cell-carcinoma", "melanoma", "skin-surgery-procedures"])

E('melanoma',
  kf=["Malignant tumour of **melanocytes**; the UK's fifth commonest cancer (about 17,500 cases a year).",
      "Risk: **UV and sunburn**, sunbeds, many or atypical naevi, fair skin, family history, previous melanoma, immunosuppression.",
      "Recognise with the **ABCDE** rule, the NICE **7-point checklist** and the **ugly duckling** sign; nodular melanoma may be EFG (elevated, firm, growing).",
      "Refer any suspicious pigmented lesion on the **suspected cancer pathway** (NICE NG12); never destroy an undiagnosed pigmented lesion.",
      "Prognosis depends mostly on **Breslow thickness** at diagnosis."],
  epi=[{"t": "**Incidence**", "sub": ["About **17,500** new cases a year in the UK; incidence has more than doubled since the 1990s.", "One of the commonest cancers in **15–34-year-olds**; median age at diagnosis in the mid-60s."]},
       {"t": "**Sex and site**", "sub": ["Men: trunk (back) most common; women: legs.", "Acral lentiginous melanoma (palms, soles, nails) is the commonest type in people with dark skin."]}],
  aet=["**UV exposure**: intermittent intense exposure and **sunburn** (especially in childhood), sunbed use.", "**Host**: many naevi (over 100), atypical naevi, fair skin type I–II, red hair, freckling.",
       "**Genetic**: family history (CDKN2A, CDK4, BAP1, MC1R variants), previous melanoma, immunosuppression, giant congenital naevus."],
  myths=["**\"Melanoma is always dark and irregular\"**: amelanotic and nodular melanomas can be pink and symmetrical.", "**\"Dark skin doesn't get melanoma\"**: acral and nail melanomas occur and are often diagnosed late."],
  patho_lead="Melanoma arises when **melanocytes** accumulate mutations that switch on growth and switch off brakes.",
  mech=[("Driver mutations", "UV-signature mutations activate the **MAPK pathway** (BRAF V600E in about half, NRAS) and inactivate tumour suppressors (CDKN2A, PTEN, TP53)."),
        ("Radial growth", "Most melanomas first spread sideways within the epidermis (superficial spreading, lentigo maligna), when cure by excision is very likely.", "v3-ssm-vs-nodular.jpg", "Superficial spreading melanoma (radial growth along the epidermis) vs nodular melanoma (early vertical growth into the dermis)."),
        ("Vertical growth", "Cells invade the dermis; deeper tumours (thicker **Breslow**) have greater metastatic risk. Nodular melanoma enters this phase early."),
        ("Immune escape", "Tumours evade T cells (e.g. via PD-L1), the basis for immunotherapy."),
        ("Metastasis", "Spread to lymph nodes, skin, lung, liver and brain.")],
  histo=["Atypical melanocytes in nests and single cells at all levels of the epidermis (**pagetoid spread**), with asymmetry and poor circumscription.",
         "Report includes **Breslow thickness**, ulceration, mitoses and margins, which guide AJCC staging and treatment."],
  special=[{"t": "**Skin of colour**", "sub": ["Look at **palms, soles and nails**: acral lentiginous melanoma and nail melanoma (Hutchinson sign) present late."]},
           {"t": "**Pregnancy and children**", "sub": ["Naevi can darken in pregnancy, but a changing lesion still needs assessment; melanoma is rare in children (Spitz-like lesions need specialist review)."]}],
  comp=["Local recurrence, in-transit metastases.", "Lymph node and distant metastasis.", "Treatment toxicity (immunotherapy immune-related adverse events)."],
  prog=["Five-year survival is over **95%** for thin (stage I) melanoma, falling with thickness and spread.", "Further primary melanomas occur in about 5–10%: lifelong skin self-checks."],
  see_also=["melanocytic-naevi", "melanoma-staging-treatment", "atypical-naevus-syndrome", "melanonychia", "seborrhoeic-keratosis"])
